files.content:
:root {
  --bg: #1b1f3b;
  --card: #252b52;
  --accent: #f7c948;
  --accent-dark: #c99a12;
  --text: #f4f6ff;
  --muted: #a9b0d6;
  --success: #5ad18a;
  --danger: #e06c75;
  --radius: 16px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: radial-gradient(circle at top, #2a3168 0%, var(--bg) 70%);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
}

.game-board {
  width: 100%;
  max-width: 520px;
  background: var(--card);
  border-radius: var(--radius);
  padding: 28px 24px 32px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.game-header h1 {
  margin: 0 0 6px;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.stat {
  background: rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  padding: 12px 10px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 0.9rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.6px;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.coin-area {
  display: flex;
  justify-content: center;
}

.coin {
  width: 180px;
  height: 180px;
  border-radius: 50%;
  border: 6px solid var(--accent-dark);
  background: radial-gradient(circle at 30% 25%, #ffe680, var(--accent) 55%, var(--accent-dark));
  color: #4a3800;
  font-size: 1.4rem;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 10px 0 var(--accent-dark), 0 16px 24px rgba(0, 0, 0, 0.35);
  transition: transform 0.08s ease, box-shadow 0.08s ease, filter 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
}

.coin:hover {
  filter: brightness(1.07);
}

.coin:focus-visible {
  outline: 4px solid #ffffff;
  outline-offset: 6px;
}

.coin:active {
  transform: translateY(6px) scale(0.98);
  box-shadow: 0 4px 0 var(--accent-dark), 0 8px 14px rgba(0, 0, 0, 0.35);
}

.coin-inner {
  pointer-events: none;
}

.upgrade-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
}

.buy-button {
  width: 100%;
  padding: 16px 20px;
  font-size: 1.1rem;
  font-weight: 700;
  font-family: inherit;
  color: #1b1f3b;
  background: var(--success);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.08s ease, filter 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 6px 0 #2f9a5f;
}

.buy-button:hover:not(:disabled) {
  filter: brightness(1.08);
}

.buy-button:focus-visible {
  outline: 4px solid #ffffff;
  outline-offset: 3px;
}

.buy-button:active:not(:disabled) {
  transform: translateY(4px);
  box-shadow: 0 2px 0 #2f9a5f;
}

.buy-button:disabled {
  background: #4a5180;
  color: var(--muted);
  box-shadow: 0 6px 0 #333a63;
  cursor: not-allowed;
}

.buy-hint {
  margin: 0;
  font-size: 0.95rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .game-board {
    padding: 22px 16px 26px;
  }

  .coin {
    width: 150px;
    height: 150px;
  }

  .stat-value {
    font-size: 1.25rem;
  }
}

(() => {
  "use strict";

  const BASE_COST = 10;
  const BASE_RATE = 1;

  const state = {
    points: 0,
    autoClickers: 0,
    nextPrice: BASE_COST
  };

  const pointsEl = document.getElementById("points");
  const countEl = document.getElementById("upgrade-count");
  const priceEl = document.getElementById("next-price");
  const coinBtn = document.getElementById("coin");
  const buyBtn = document.getElementById("buy-upgrade");

  function render() {
    pointsEl.textContent = String(Math.floor(state.points));
    countEl.textContent = String(state.autoClickers);
    priceEl.textContent = String(state.nextPrice);

    const affordable = state.points >= state.nextPrice;
    buyBtn.disabled = !affordable;
    buyBtn.setAttribute("aria-disabled", String(!affordable));
    buyBtn.setAttribute(
      "aria-label",
      affordable
        ? `Buy Auto-clicker for ${state.nextPrice} points`
        : `Auto-clicker costs ${state.nextPrice} points, not enough points yet`
    );
  }

  function addPoints(amount) {
    state.points = Math.min(state.points + amount, Number.MAX_SAFE_INTEGER);
    render();
  }

  coinBtn.addEventListener("click", () => {
    addPoints(1);
  });

  buyBtn.addEventListener("click", () => {
    if (state.points < state.nextPrice) return;
    state.points -= state.nextPrice;
    state.autoClickers += 1;
    state.nextPrice = Math.min(state.nextPrice * 2, Number.MAX_SAFE_INTEGER);
    render();
  });

  setInterval(() => {
    if (state.autoClickers > 0) {
      addPoints(state.autoClickers * BASE_RATE);
    }
  }, 1000);

  render();
})();
